int n;

void printSums(int N)
{
    int start = 1, end = 1;
    int sum = 1;
    while (start <= N / 2)
    {
        if (sum < N)
        {
            end++;
            sum += end;
        }
        else if (sum > N)
        {
            sum -= start;
            start++;
        }
        else
        {
            for (int i = start; i <= end; i++)
            {
                printf("%d ", i);
            }
            printf("\n");
            sum -= start;
            start++;
        }
    }
}

int main()
{
    if (scanf("%d", &n) == 1)
    {
        printSums(n);
    }
    return 0;
