int findmax(int* Count) {
    int m = 0;
    for (int i = 0; i < 26; i++) if (Count[i] > m) m = Count[i];
    return m;
}

int first_occ[100005], dummy[26];

int max2(int a, int b) {
    if (a > b) return a;
    return b;
}

int get_cand(int cur, int j) {
    if (cur >= -1) return j;
    int p = first_occ[-(cur + 1)];
    if (p == -1) return 0;
    return j - p;
}

void mark_occ(int cur, int j) {
    if (cur < 0) if (first_occ[-cur] == -1) first_occ[-cur] = j;
}

int solve_char(char *s, int n, char c) {
    memset(first_occ, -1, (n + 2) * sizeof(int));
    int cur = 0, ans = 0;
    for (int j = 1; j <= n; j++) {
        cur += (s[j - 1] == c) * 2 - 1;
        ans = max2(ans, get_cand(cur, j));
        mark_occ(cur, j);
    }
    return ans;
}

int solve_all(char *s, int n) {
    int ans = 0;
    for (int c = 0; c < 26; c++) ans = max2(ans, solve_char(s, n, 'a' + c));
    return ans;
}

void run_case(char *s) {
    int n;
    findmax(dummy);
    if (scanf("%d %s", &n, s) == 2) printf("%d\n", solve_all(s, n));
}

int main() {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    char *s = malloc(100005);
    while (t--) run_case(s);
    return 0;
}

