#define MAXP 100
#define BUFLEN 105

char *gems[]={"NONE","Garnet","Amethyst","Aquamarine","Diamond","Emerald","Pearl","Ruby","Peridot","Sapphire","Tourmaline","Topaz","Lapis",0};
char ponies[MAXP][BUFLEN];
int gem_rank[MAXP];

int gem_index(char *s) {
    for (int i = 1; gems[i]; i++) {
        if (strcmp(s, gems[i]) == 0) return i;
    }
    return 0;
}

int get_rank(char *name) {
    char buf[BUFLEN];
    strcpy(buf, name);
    int max_r = 0;
    char *token = strtok(buf, " ");
    while (token) {
        int r = gem_index(token);
        if (r > max_r) max_r = r;
        token = strtok(NULL, " ");
    }
    return max_r;
}

int cmp(const void *pa, const void *pb) {
    int a = *(int *)pa, b = *(int *)pb;
    if (gem_rank[a] != gem_rank[b])
        return gem_rank[b] - gem_rank[a];
    int res = strcasecmp(ponies[a], ponies[b]);
    if (res != 0) return res;
    return strcmp(ponies[a],ponies[b])>0;
}

int main() {
    int n = 0;
    int idx[MAXP];
    while (fgets(ponies[n], BUFLEN, stdin)) {
        ponies[n][strcspn(ponies[n], "\r\n")] = 0;
        if (strcmp(ponies[n], "END") == 0) break;
        gem_rank[n] = get_rank(ponies[n]);
        idx[n] = n;
        n++;
    }
    qsort(idx, n, sizeof(int), cmp);
    for (int i = 0; i < n; i++) {
        puts(ponies[idx[i]]);
    }
    return 0;
}

