int A[309][309];
bool ok[309][309][309];

void solve() {
    int R, C, L;
    if (!(cin >> R >> C >> L)) return;
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            cin >> A[r][c];
        }
    }
    for (int r = 0; r < R; r++) {
        for (int c1 = 0; c1 < C; c1++) {
            int mn = A[r][c1], mx = A[r][c1];
            for (int c2 = c1; c2 < C; c2++) {
                mn = min(mn, A[r][c2]);
                mx = max(mx, A[r][c2]);
                ok[r][c1][c2] = (mx - mn <= L);
            }
        }
    }
    int best = 0;
    for (int c1 = 0; c1 < C; c1++) {
        for (int c2 = c1; c2 < C; c2++) {
            int w = c2 - c1 + 1;
            int h = 0;
            for (int r = 0; r < R; r++) {
                if (ok[r][c1][c2]) {
                    h++;
                    best = max(best, h * w);
                } else {
                    h = 0;
                }
            }
        }
    }
    cout << best << endl;
}

