void bubble_sort(int arr[],int no){
    for(int i=0; i<no-1; i++){
        for(int j=0; j<no-1-i; j++){
            if(arr[j] > arr[j+1]){
                int t = arr[j]; arr[j] = arr[j+1]; arr[j+1] = t;
            }
        }
    }
}

int MEGA_SALE(int arr[],int no,int k){
    bubble_sort(arr, no);
    int sum = 0;
    for(int i=0; i<k && i<no; i++){
        if(arr[i] < 0) sum -= arr[i];
    }
    return sum;
}

